51	 */
52	@GwtCompatible
53	public final class Ints extends IntsMethodsForWeb {
54	  private Ints() {}
55	
56	  /**
57	   * The number of bytes required to represent a primitive {@code int} value.
58	   *
59	   * <p>Prefer {@link Integer#BYTES} instead.
60	   */
61	  public static final int BYTES = Integer.BYTES;
62	
63	  /**
64	   * The largest power of two that can be represented as an {@code int}.
65	   *
66	   * @since 10.0
67	   */
68	  public static final int MAX_POWER_OF_TWO = 1 << (Integer.SIZE - 2);
69	
70	  /**
71	   * Returns a hash code for {@code value}; obsolete alternative to {@link Integer#hashCode(int)}.
72	   *
73	   * @param value a primitive {@code int} value
74	   * @return a hash code for the value
75	   */
76	  @InlineMe(replacement = "Integer.hashCode(value)")
77	  @InlineMeValidationDisabled(
78	      "The hash code of a int is the int itself, so it's simplest to return that.")
79	  public static int hashCode(int value) {
80	    return value;
81	  }
82	
83	  /**
84	   * Returns the {@code int} value that is equal to {@code value}, if possible.
85	   *
86	   * <p><b>Note:</b> this method is now unnecessary and should be treated as deprecated. Use {@link
87	   * Math#toIntExact(long)} instead, but be aware that that method throws {@link
88	   * ArithmeticException} rather than {@link IllegalArgumentException}.
89	   *
90	   * @param value any value in the range of the {@code int} type
91	   * @return the {@code int} value that equals {@code value}
92	   * @throws IllegalArgumentException if {@code value} is greater than {@link Integer#MAX_VALUE} or
93	   *     less than {@link Integer#MIN_VALUE}
94	   */
95	  public static int checkedCast(long value) {
96	    int result = (int) value;
97	    checkArgument(result == value, "Out of range: %s", value);
98	    return result;
99	  }
100	
101	  /**
102	   * Returns the {@code int} nearest in value to {@code value}.
103	   *
104	   * @param value any {@code long} value
105	   * @return the same value cast to {@code int} if it is in the range of the {@code int} type,
106	   *     {@link Integer#MAX_VALUE} if it is too large, or {@link Integer#MIN_VALUE} if it is too
107	   *     small
108	   */
109	  public static int saturatedCast(long value) {
110	    if (value > Integer.MAX_VALUE) {
111	      return Integer.MAX_VALUE;
112	    }
113	    if (value < Integer.MIN_VALUE) {
114	      return Integer.MIN_VALUE;
115	    }
116	    return (int) value;
117	  }
