119	  /**
120	   * Compares the two specified {@code int} values. The sign of the value returned is the same as
121	   * that of {@code ((Integer) a).compareTo(b)}.
122	   *
123	   * <p><b>Note:</b> this method is now unnecessary and should be treated as deprecated; use the
124	   * equivalent {@link Integer#compare} method instead.
125	   *
126	   * @param a the first {@code int} to compare
127	   * @param b the second {@code int} to compare
128	   * @return a negative value if {@code a} is less than {@code b}; a positive value if {@code a} is
129	   *     greater than {@code b}; or zero if they are equal
130	   */
131	  @InlineMe(replacement = "Integer.compare(a, b)")
132	  public static int compare(int a, int b) {
133	    return Integer.compare(a, b);
134	  }
135	
136	  /**
137	   * Returns {@code true} if {@code target} is present as an element anywhere in {@code array}.
138	   *
139	   * @param array an array of {@code int} values, possibly empty
140	   * @param target a primitive {@code int} value
141	   * @return {@code true} if {@code array[i] == target} for some value of {@code i}
142	   */
143	  public static boolean contains(int[] array, int target) {
144	    for (int value : array) {
145	      if (value == target) {
146	        return true;
147	      }
148	    }
149	    return false;
150	  }
151	
152	  /**
153	   * Returns the index of the first appearance of the value {@code target} in {@code array}.
154	   *
155	   * @param array an array of {@code int} values, possibly empty
156	   * @param target a primitive {@code int} value
157	   * @return the least index {@code i} for which {@code array[i] == target}, or {@code -1} if no
158	   *     such index exists.
159	   */
160	  public static int indexOf(int[] array, int target) {
161	    return indexOf(array, target, 0, array.length);
162	  }
163	
164	  // TODO(kevinb): consider making this public
165	  private static int indexOf(int[] array, int target, int start, int end) {
166	    for (int i = start; i < end; i++) {
167	      if (array[i] == target) {
168	        return i;
169	      }
170	    }
171	    return -1;
172	  }
173	
174	  /**
175	   * Returns the start position of the first occurrence of the specified {@code target} within
176	   * {@code array}, or {@code -1} if there is no such occurrence.
177	   *
178	   * <p>More formally, returns the lowest index {@code i} such that {@code Arrays.copyOfRange(array,
179	   * i, i + target.length)} contains exactly the same elements as {@code target}.
180	   *
181	   * @param array the array to search for the sequence {@code target}
182	   * @param target the array to search for as a sub-sequence of {@code array}
183	   */
184	  public static int indexOf(int[] array, int[] target) {
185	    checkNotNull(array, "array");
186	    checkNotNull(target, "target");
187	    if (target.length == 0) {
188	      return 0;
189	    }
190	
191	    outer:
192	    for (int i = 0; i < array.length - target.length + 1; i++) {
193	      for (int j = 0; j < target.length; j++) {
194	        if (array[i + j] != target[j]) {
195	          continue outer;
196	        }
197	      }
198	      return i;
199	    }
200	    return -1;

