77	  /** Creates and returns a properly-sized array with the given number of buckets. */
78	  static Object createTable(int buckets) {
79	    if (buckets < 2
80	        || buckets > Ints.MAX_POWER_OF_TWO
81	        || Integer.highestOneBit(buckets) != buckets) {
82	      throw new IllegalArgumentException("must be power of 2 between 2^1 and 2^30: " + buckets);
83	    }
